#nullable enable

using System.IO.Compression;
using System.Security.Cryptography;
using System.Text;
using Jint.Native.Intl.Data;

namespace Jint.Tests.Runtime;

/// <summary>
/// <c>DateTimeCalendarPatterns.bin</c> and its loader, <see cref="DateTimeCalendarPatternData"/>: CLDR 48.2's patterns
/// and names for the calendars other than the Gregorian one, generated by <c>tools/cldr-dates</c>
/// (sebastienros/jint#4204).
/// </summary>
/// <remarks>
/// These pin the data and the loader apart from the formatter that reads them (<see cref="IntlDateTimeFormatCalendarTests"/>):
/// that the embedded resource is the one its generated header describes and follows <c>DateTimePatterns.bin</c>'s
/// locales, that every locale of every calendar is rebuilt complete, and that the values ICU decides by which locale
/// defines them are the ones it reads. The expected values are CLDR's, read from cldr-json and CLDR's XML rather than from
/// the loader.
/// </remarks>
public class IntlDateTimeCalendarPatternDataTests
{
    private const string ResourceName = "Jint.Native.Intl.Data.DateTimeCalendarPatterns.bin";

    private static DateTimeCalendarPatternData Data => DateTimeCalendarPatternData.Shared;

    private static DateTimePatternLocale Calendar(string locale, string calendar) => Data.GetLocale(locale, DateTimeCalendarPatternData.CalendarOf(calendar));

    /// <summary>
    /// Decodes the resource independently of the loader and hashes what it holds: the constants the generator wrote
    /// beside it must describe it, and its blocks must be <c>DateTimePatterns.bin</c>'s languages with their locales.
    /// </summary>
    [Test]
    public void TheEmbeddedResourceIsTheOneItsGeneratedHeaderDescribes()
    {
        byte[] file;
        using (var stream = typeof(Engine).Assembly.GetManifestResourceStream(ResourceName)!)
        using (var buffer = new MemoryStream())
        {
            stream.CopyTo(buffer);
            file = buffer.ToArray();
        }

        Encoding.ASCII.GetString(file, 0, 4).Should().Be("JDTC");
        file[4].Should().Be(1);
        var position = 5;
        var indexRawLength = ReadVarint(file, ref position);
        var indexCompressedLength = ReadVarint(file, ref position);
        var index = Inflate(file, position, indexCompressedLength, indexRawLength);
        var blockArea = position + indexCompressedLength;

        var indexPosition = 0;
        ReadString(index, ref indexPosition).Should().Be(DateTimeCalendarPatternData.CldrVersion);
        var calendarCount = ReadVarint(index, ref indexPosition);
        calendarCount.Should().Be(DateTimeCalendarPatternData.CalendarCount);
        var names = new List<string>();
        for (var c = 0; c < calendarCount; c++)
        {
            names.Add(ReadString(index, ref indexPosition));
            var identifiers = ReadVarint(index, ref indexPosition);
            for (var i = 0; i < identifiers; i++)
            {
                ReadString(index, ref indexPosition);
            }

            ReadVarint(index, ref indexPosition);
            var eras = ReadVarint(index, ref indexPosition);
            for (var i = 0; i < eras; i++)
            {
                ReadString(index, ref indexPosition);
            }

            var slots = ReadVarint(index, ref indexPosition);
            for (var i = 0; i < slots; i++)
            {
                ReadString(index, ref indexPosition);
            }
        }

        names.Should().Equal("buddhist", "japanese", "roc", "hebrew", "persian", "indian", "coptic", "ethiopic", "ethiopic-amete-alem", "islamic");

        using var payload = new MemoryStream();
        payload.Write(index, 0, index.Length);
        var gregorianLocales = DateTimePatternData.Shared.Locales;
        var blockCount = ReadVarint(index, ref indexPosition);
        var locales = 0;
        var blockEnd = blockArea;
        for (var block = 0; block < blockCount; block++)
        {
            var language = ReadString(index, ref indexPosition);
            var offset = ReadVarint(index, ref indexPosition);
            var compressedLength = ReadVarint(index, ref indexPosition);
            var rawLength = ReadVarint(index, ref indexPosition);
            var raw = Inflate(file, blockArea + offset, compressedLength, rawLength);
            payload.Write(raw, 0, raw.Length);
            blockEnd = Math.Max(blockEnd, blockArea + offset + compressedLength);
            var localeCount = ReadVarint(index, ref indexPosition);
            for (var i = 0; i < localeCount; i++)
            {
                gregorianLocales[locales + i].Split('-')[0].Should().Be(language);
            }

            locales += localeCount;
        }

        indexPosition.Should().Be(index.Length);
        locales.Should().Be(DateTimeCalendarPatternData.LocaleCount).And.Be(gregorianLocales.Count);
        blockEnd.Should().Be(file.Length, "the blocks end where the resource does");
        Sha256(payload.ToArray()).Should().Be(DateTimeCalendarPatternData.PayloadSha256);
    }

    /// <summary>
    /// The calendars the data serves, by ECMA-402 identifier: one Islamic data set for all five Islamic identifiers, and
    /// none for the calendars written with the Gregorian data or in a lane of their own.
    /// </summary>
    [Test]
    public void EachIdentifierFindsItsCalendar()
    {
        foreach (var identifier in new[] { "gregory", "iso8601", "chinese", "dangi", "my-calendar", "Buddhist" })
        {
            DateTimeCalendarPatternData.CalendarOf(identifier).Should().Be(-1, identifier);
        }

        DateTimeCalendarPatternData.CalendarOf(null).Should().Be(-1);
        var islamic = DateTimeCalendarPatternData.CalendarOf("islamic");
        foreach (var identifier in new[] { "islamic-civil", "islamic-rgsa", "islamic-tbla", "islamic-umalqura" })
        {
            DateTimeCalendarPatternData.CalendarOf(identifier).Should().Be(islamic, identifier);
        }

        DateTimeCalendarPatternData.CalendarOf("ethioaa").Should().NotBe(DateTimeCalendarPatternData.CalendarOf("ethiopic"));
        Calendar("en", "islamic-umalqura").Calendar.Should().Be("islamic");
        Calendar("en", "ethioaa").Calendar.Should().Be("ethiopic-amete-alem");
    }

    /// <summary>
    /// Every locale of every calendar is rebuilt through its parents with every pattern and name in place, and its
    /// parent is the same calendar's.
    /// </summary>
    [Test]
    public void EveryLocaleOfEveryCalendarIsComplete()
    {
        var problems = new List<string>();
        var identifiers = new[] { "buddhist", "japanese", "roc", "hebrew", "persian", "indian", "coptic", "ethiopic", "ethioaa", "islamic-civil" };
        foreach (var locale in DateTimePatternData.Shared.Locales)
        {
            foreach (var identifier in identifiers)
            {
                var data = Calendar(locale, identifier);
                var label = locale + " " + identifier;
                if (!string.Equals(data.Locale, locale, StringComparison.Ordinal))
                {
                    problems.Add(label + ": is " + data.Locale);
                }

                if (data.Parent is { } parent
                    && (!string.Equals(parent.Locale, DateTimePatternData.Shared.GetParentLocale(locale), StringComparison.Ordinal)
                        || !string.Equals(parent.Calendar, data.Calendar, StringComparison.Ordinal)))
                {
                    problems.Add(label + ": its parent is " + parent.Locale + " " + parent.Calendar);
                }

                for (var width = DateTimeStyleWidth.Full; width <= DateTimeStyleWidth.Short; width++)
                {
                    if (data.GetDateFormat(width).Length == 0 || data.GetTimeFormat(width).Length == 0 || !data.GetAtTimeFormat(width).Contains("{1}", StringComparison.Ordinal))
                    {
                        problems.Add(label + ": a " + width + " style is missing");
                    }
                }

                var monthCount = identifier switch
                {
                    "buddhist" or "japanese" or "roc" => 12,
                    "hebrew" => 14,
                    "coptic" or "ethiopic" or "ethioaa" => 13,
                    _ => 12,
                };

                foreach (var context in new[] { DateTimeNameContext.Format, DateTimeNameContext.StandAlone })
                {
                    foreach (var width in new[] { DateTimeNameWidth.Abbreviated, DateTimeNameWidth.Wide, DateTimeNameWidth.Narrow })
                    {
                        var months = data.GetMonthNames(context, width);
                        if (months.Length != monthCount || months.ToArray().Any(string.IsNullOrEmpty))
                        {
                            problems.Add($"{label}: {context} {width} has {months.Length} months");
                        }
                    }
                }

                var eraCount = Data.EraKeys(DateTimeCalendarPatternData.CalendarOf(identifier)).Length;
                if (data.GetEraNames(DateTimeNameWidth.Abbreviated).Length != eraCount || data.GetEraNames(DateTimeNameWidth.Wide).ToArray().Any(string.IsNullOrEmpty))
                {
                    problems.Add(label + ": the eras are incomplete");
                }

                if (data.AvailableFormats.Length == 0 || data.IntervalFormats.Length == 0)
                {
                    problems.Add(label + ": no availableFormats or intervalFormats");
                }
            }
        }

        problems.Should().BeEmpty();
    }

    /// <summary>CLDR's names, as cldr-json resolves them.</summary>
    [Test]
    public void TheNamesAreTheCalendarsOwn()
    {
        Calendar("en", "buddhist").GetEraNames(DateTimeNameWidth.Abbreviated).ToArray().Should().Equal("BE");
        Data.EraKeys(DateTimeCalendarPatternData.CalendarOf("japanese")).ToArray().Should().Equal("232", "233", "234", "235", "236");
        Calendar("ja", "japanese").GetEraNames(DateTimeNameWidth.Wide).ToArray().Should().Equal("明治", "大正", "昭和", "平成", "令和");
        Calendar("ar", "islamic-umalqura").GetEraNames(DateTimeNameWidth.Abbreviated).ToArray().Should().Equal("هـ", "BH");
        Calendar("en", "hebrew").GetMonthNames(DateTimeNameContext.Format, DateTimeNameWidth.Wide).ToArray().Should().Equal(
            "Tishri", "Heshvan", "Kislev", "Tevet", "Shevat", "Adar I", "Adar", "Nisan", "Iyar", "Sivan", "Tamuz", "Av", "Elul", "Adar II");

        // A calendar writing the Gregorian months writes the locale's Gregorian names, and every calendar its weekdays.
        Calendar("de", "buddhist").GetMonthNames(DateTimeNameContext.Format, DateTimeNameWidth.Wide).ToArray()
            .Should().Equal(DateTimePatternData.Shared.GetLocale("de").GetMonthNames(DateTimeNameContext.Format, DateTimeNameWidth.Wide).ToArray());
        Calendar("de", "hebrew").GetWeekdayNames(DateTimeNameContext.Format, DateTimeNameWidth.Wide).ToArray()
            .Should().Equal(DateTimePatternData.Shared.GetLocale("de").GetWeekdayNames(DateTimeNameContext.Format, DateTimeNameWidth.Wide).ToArray());
    }

    /// <summary>
    /// The values ICU decides by which locale defines them (<c>tools/cldr-dates/Jint.CldrDates.Generator/CldrXml.cs</c>).
    /// </summary>
    [Test]
    public void TheValuesIcuReadsByWhoDefinesThemAreIcus()
    {
        // en-GB defines no Buddhist or generic date patterns, so ICU reads en-001's array, twelve-hour times and all.
        Calendar("en-GB", "buddhist").GetTimeFormat(DateTimeStyleWidth.Short).Should().Be("h:mm a");
        DateTimePatternData.Shared.GetLocale("en-GB").GetTimeFormat(DateTimeStyleWidth.Short).Should().Be("HH:mm");
        Calendar("es-MX", "buddhist").GetTimeFormat(DateTimeStyleWidth.Short).Should().Be("h:mm a");

        // zh-Hant defines Gregorian atTime patterns, its short one identical to its standard pattern; ICU joins every
        // calendar's date and time with them.
        Calendar("zh-Hant", "buddhist").GetAtTimeFormat(DateTimeStyleWidth.Short).Should().Be("{1} {0}");

        // Latvian defines none, so ICU joins with the calendar's own joining patterns.
        Calendar("lv", "buddhist").GetAtTimeFormat(DateTimeStyleWidth.Medium).Should().Be("{1}, {0}");
        DateTimePatternData.Shared.GetLocale("lv").GetAtTimeFormat(DateTimeStyleWidth.Medium).Should().Be("{1} {0}");

        // A range's date and time are joined as the Gregorian calendar joins them, whatever the calendar.
        Calendar("lv", "buddhist").GetDateTimeFormat(DateTimeStyleWidth.Medium)
            .Should().Be(DateTimePatternData.Shared.GetLocale("lv").GetDateTimeFormat(DateTimeStyleWidth.Medium));

        // The availableFormats Japanese defines for the Buddhist calendar itself come before the generic calendar's.
        var ja = Calendar("ja", "buddhist");
        ja.OwnCalendarFormats.ToArray().Should().Contain(["Gy", "y", "yyyyMd"]).And.NotContain("Hm");
        ja.TryGetAvailableFormat("Gy", out var pattern).Should().BeTrue();
        pattern.Should().Be("GGGGy年");
        DateTimePatternData.Shared.GetLocale("ja").OwnCalendarFormats.Length.Should().Be(0);
    }

    /// <summary>
    /// A calendar is inflated only when it is asked for, in the languages it is asked for in.
    /// </summary>
    [Test]
    public void ABlockIsReadOnlyForACalendarAskedForInItsLanguage()
    {
        var data = new DateTimeCalendarPatternData(() => typeof(Engine).Assembly.GetManifestResourceStream(ResourceName)!, DateTimePatternData.Shared);
        var buddhist = data.GetLocale("de-AT", DateTimeCalendarPatternData.CalendarOf("buddhist"));
        buddhist.Locale.Should().Be("de-AT");
        buddhist.Parent!.Locale.Should().Be("de");
        data.GetLocale("de-AT", DateTimeCalendarPatternData.CalendarOf("buddhist")).Should().BeSameAs(buddhist);
        data.GetLocale("de-DE", DateTimeCalendarPatternData.CalendarOf("buddhist")).Locale.Should().Be("de");
    }

    private static int ReadVarint(byte[] bytes, ref int position)
    {
        var result = 0;
        for (var shift = 0; ; shift += 7)
        {
            var b = bytes[position++];
            result |= (b & 0x7F) << shift;
            if (b < 0x80)
            {
                return result;
            }
        }
    }

    private static string ReadString(byte[] bytes, ref int position)
    {
        var length = ReadVarint(bytes, ref position);
        var value = Encoding.UTF8.GetString(bytes, position, length);
        position += length;
        return value;
    }

    private static byte[] Inflate(byte[] file, int offset, int compressedLength, int rawLength)
    {
        using var inflate = new DeflateStream(new MemoryStream(file, offset, compressedLength), CompressionMode.Decompress);
        var raw = new byte[rawLength];
        var read = 0;
        while (read < raw.Length)
        {
            var count = inflate.Read(raw, read, raw.Length - read);
            if (count == 0)
            {
                break;
            }

            read += count;
        }

        read.Should().Be(rawLength);
        return raw;
    }

    private static string Sha256(byte[] bytes)
    {
        using var sha = SHA256.Create();
        return string.Concat(sha.ComputeHash(bytes).Select(b => b.ToString("x2", System.Globalization.CultureInfo.InvariantCulture)));
    }
}
